app.patch('/api/orders/:id/status',auth,async(req,res)=>{const s=String(req.body.status||'').slice(0,40);const allowed=['PAYMENT PENDING','Order created','Payment confirmed','Restaurant accepted','Preparing','Food ready','Rider assigned','Rider accepted','Rider arrived','Food picked up','Going to customer','Arrived at customer','Customer PIN verified','Completed'];if(!allowed.includes(s))return res.status(400).json({error:'Invalid order status'});if(pool){const existing=(await q('select * from orders where id=$1',[req.params.id]))[0];if(!existing)return res.status(404).json({error:'Order not found'});const canCustomer=existing.customer_phone===req.user.phone;const canRider=existing.rider_phone===req.user.phone&&req.user.role==='rider';let canVendor=false;if(req.user.role==='vendor'){const vp=await getRoleProfile(req.user.phone,'vendor');canVendor=!!vp&&vp.status==='approved'&&existing.vendor===vp.business_name;}const canAdmin=['admin','superadmin'].includes(req.user.role);if(!canCustomer&&!canRider&&!canVendor&&!canAdmin)return res.status(403).json({error:'Not allowed to update this order'});const r=await q('update orders set status=$1,updated_at=now(),rider_phone=case when $2 is not null then $2 else rider_phone end where id=$3 returning *',[s,canRider?req.user.phone:null,req.params.id]);await audit(req.user.phone,'order.status','order',req.params.id,{status:s});return res.json(r[0])}const o=memory.orders.get(req.params.id);if(!o)return res.status(404).json({error:'Order not found'});let memoryAllowed=false;if(o.customer_phone===req.user.phone||['admin','superadmin'].includes(req.user.role))memoryAllowed=true;if(req.user.role==='rider'&&o.rider_phone===req.user.phone)memoryAllowed=true;if(req.user.role==='vendor'){const vp=await getRoleProfile(req.user.phone,'vendor');memoryAllowed=!!vp&&vp.status==='approved'&&o.vendor===vp.business_name;}if(!memoryAllowed)return res.status(403).json({error:'Not allowed'});o.status=s;o.updated_at=new Date().toISOString();if(req.user.role==='rider')o.rider_phone=req.user.phone;res.json(o)});
app.post('/api/bookings',auth,async(req,res)=>{const id=makeId('OBU-HL-'),b={id,customer_phone:req.user.phone,hotel:req.body.hotel||'Obuasi Royal Hotel',room:req.body.room||'Executive Room',total:Number(req.body.total||450),status:'BOOKED',created_at:new Date().toISOString()};if(pool)await q('insert into bookings(id,customer_phone,hotel,room,total,status) values($1,$2,$3,$4,$5,$6)',[id,b.customer_phone,b.hotel,b.room,b.total,b.status]);else memory.bookings.set(id,b);await audit(req.user.phone,'booking.created','booking',id);res.status(201).json(b)});
