app.patch('/api/bookings/:id/status',auth,async(req,res)=>{const s=String(req.body.status||'').slice(0,40);if(!['BOOKED','CHECKED IN','CHECKED OUT','CANCELLED'].includes(s))return res.status(400).json({error:'Invalid booking status'});if(pool){const existing=(await q('select * from bookings where id=$1',[req.params.id]))[0];if(!existing)return res.status(404).json({error:'Booking not found'});let canHotel=false;if(req.user.role==='hotel'){const hp=await getRoleProfile(req.user.phone,'hotel');canHotel=!!hp&&hp.status==='approved'&&hp.business_name===existing.hotel;}if(existing.customer_phone!==req.user.phone&&!canHotel&&!['admin','superadmin'].includes(req.user.role))return res.status(403).json({error:'Not allowed'});const r=await q('update bookings set status=$1,updated_at=now() where id=$2 returning *',[s,req.params.id]);await audit(req.user.phone,'booking.status','booking',req.params.id,{status:s});return res.json(r[0])}const b=memory.bookings.get(req.params.id);if(!b)return res.status(404).json({error:'Booking not found'});let allowed=false;if(b.customer_phone===req.user.phone||['admin','superadmin'].includes(req.user.role))allowed=true;if(req.user.role==='hotel'){const hp=await getRoleProfile(req.user.phone,'hotel');allowed=!!hp&&hp.status==='approved'&&hp.business_name===b.hotel;}if(!allowed)return res.status(403).json({error:'Not allowed'});b.status=s;res.json(b)});
app.get('/api/bookings/:id/qr',auth,async(req,res)=>{const booking=pool?(await q('select id,customer_phone,hotel,room,status,created_at from bookings where id=$1',[req.params.id]))[0]:memory.bookings.get(req.params.id);if(!booking)return res.status(404).json({error:'Booking not found'});if(booking.customer_phone!==req.user.phone&&!['hotel','admin','superadmin'].includes(req.user.role))return res.status(403).json({error:'Not allowed'});const token=jwt.sign({bookingId:booking.id,hotel:booking.hotel,customer:booking.customer_phone,nonce:crypto.randomBytes(8).toString('hex')},SIGNING_SECRET,{expiresIn:'30m'});const qrData=await QRCode.toDataURL(token,{width:440,margin:2});res.json({bookingId:booking.id,qrToken:token,qrData,expiresIn:1800})});
app.post('/api/hotel/checkin/scan',auth,roles('hotel','admin','superadmin'),async(req,res)=>{try{const c=jwt.verify(String(req.body.qrToken||''),SIGNING_SECRET);const b=pool?(await q('select * from bookings where id=$1',[c.bookingId]))[0]:memory.bookings.get(c.bookingId);if(!b)return res.status(404).json({error:'Booking not found'});if(req.user.role==='hotel'){const hp=await getRoleProfile(req.user.phone,'hotel');if(!hp||hp.status!=='approved'||hp.business_name!==b.hotel)return res.status(403).json({error:'Booking belongs to another hotel'});}if(b.status!=='BOOKED')return res.status(400).json({error:'Booking is not available for check-in'});if(pool){const r=await q("update bookings set status='CHECKED IN',updated_at=now() where id=$1 returning *",[b.id]);await audit(req.user.phone,'hotel.checkin','booking',b.id);return res.json({ok:true,booking:r[0]})}b.status='CHECKED IN';res.json({ok:true,booking:b})}catch{return res.status(400).json({error:'Invalid or expired QR code'})}});
async function flw(pathname,body){const r=await fetch('https://api.flutterwave.com/v3'+pathname,{method:'POST',headers:{Authorization:'Bearer '+process.env.FLW_SECRET_KEY,'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.message||'Flutterwave error');return d}
app.post('/api/payments/checkout',auth,async(req,res)=>{if(!process.env.FLW_SECRET_KEY)return res.status(503).json({error:'Flutterwave is not configured'});const amount=Number(req.body.amount);if(!(amount>0))return res.status(400).json({error:'Invalid amount'});const tx_ref='OBG-'+Date.now()+'-'+crypto.randomBytes(3).toString('hex');const base=process.env.APP_URL||`${req.protocol}://${req.get('host')}`;try{const d=await flw('/payments',{tx_ref,amount,currency:'GHS',redirect_url:`${base}/payment-return`,customer:{email:req.body.email||`${req.user.phone.replace('+','')}@obuasigo.app`,name:req.body.name||'ObuasiGo Customer',phonenumber:req.user.phone},payment_options:'card,ghanamobilemoney',customizations:{title:'ObuasiGo',description:req.body.description||'ObuasiGo order payment'},meta:{entity_type:req.body.entityType||'order',entity_id:req.body.entityId||''}});if(pool)await q('insert into payments(tx_ref,user_phone,entity_type,entity_id,amount,currency,status) values($1,$2,$3,$4,$5,$6,$7)',[tx_ref,req.user.phone,req.body.entityType||'order',req.body.entityId||'',amount,'GHS','pending']);else memory.payments.set(tx_ref,{tx_ref,user_phone:req.user.phone,amount,status:'pending'});res.json({ok:true,tx_ref,link:d.data?.link})}catch(e){res.status(502).json({error:e.message})}});
app.get('/api/payments/verify/:transactionId',auth,async(req,res)=>{
 if(!process.env.FLW_SECRET_KEY)return res.status(503).json({error:'Flutterwave is not configured'});
 try{
  const r=await fetch(`https://api.flutterwave.com/v3/transactions/${encodeURIComponent(req.params.transactionId)}/verify`,{headers:{Authorization:'Bearer '+process.env.FLW_SECRET_KEY}});
  const d=await r.json(); if(!r.ok)return res.status(502).json({error:d.message||'Payment provider verification failed'});
  const tx=d.data||{}; const ref=String(tx.tx_ref||'');
  let payment=null;
  if(pool) payment=(await q('select * from payments where tx_ref=$1 and user_phone=$2',[ref,req.user.phone]))[0]||null;
  else payment=[...memory.payments.values()].find(x=>x.tx_ref===ref&&x.user_phone===req.user.phone)||null;
  if(!payment)return res.status(403).json({error:'Payment does not belong to this account'});
  const paid=String(tx.status||'').toLowerCase()==='successful';
  if(payment.amount!=null && Number(tx.amount)!==Number(payment.amount))return res.status(400).json({error:'Payment amount mismatch'});
  if(payment.currency && String(tx.currency||'').toUpperCase()!==String(payment.currency).toUpperCase())return res.status(400).json({error:'Payment currency mismatch'});
  const newStatus=paid?'successful':String(tx.status||'pending');
  if(pool)await q('update payments set status=$1,transaction_id=$2 where tx_ref=$3 and user_phone=$4',[newStatus,String(tx.id||req.params.transactionId),ref,req.user.phone]);
  else payment.status=newStatus;
  if(paid && payment.entity_type==='order' && payment.entity_id){
    if(pool){await q("update orders set status='Payment confirmed',updated_at=now() where id=$1 and customer_phone=$2",[payment.entity_id,req.user.phone]);await qualifyReferralForUser(req.user.phone)}
    else {const o=memory.orders.get(payment.entity_id);if(o&&o.customer_phone===req.user.phone){o.status='Payment confirmed';await qualifyReferralForUser(req.user.phone)}}
  }
  res.json({ok:true,status:newStatus,transactionId:tx.id,tx_ref:ref,amount:tx.amount,currency:tx.currency,entityType:payment.entity_type,entityId:payment.entity_id});
 }catch(e){res.status(502).json({error:e.message})}
});
app.post('/api/webhooks/flutterwave',async(req,res)=>{const hash=req.headers['verif-hash'];if(!process.env.FLW_SECRET_HASH||hash!==process.env.FLW_SECRET_HASH)return res.status(401).end();const body=req.body||{};const tx=body.data||body;const ref=tx.tx_ref;if(ref){if(pool){await q('update payments set status=$1,transaction_id=$2 where tx_ref=$3',[tx.status||'completed',String(tx.id||''),ref]);const pay=(await q('select entity_type,entity_id,status from payments where tx_ref=$1',[ref]))[0];if(pay?.entity_type==='order'&&pay.entity_id&&String(tx.status||'').toLowerCase()==='successful'){await q("update orders set status='Payment confirmed',updated_at=now() where id=$1",[pay.entity_id]);const order=(await q('select customer_phone from orders where id=$1',[pay.entity_id]))[0];if(order?.customer_phone)await qualifyReferralForUser(order.customer_phone)}}else if(memory.payments.has(ref)){const pay=memory.payments.get(ref);pay.status=tx.status||'completed';if(pay.entity_type==='order'&&pay.entity_id&&String(tx.status||'').toLowerCase()==='successful'){const o=memory.orders.get(pay.entity_id);if(o){o.status='Payment confirmed';await qualifyReferralForUser(o.customer_phone)}}}}res.json({ok:true})});
