app.patch('/api/admin/documents/:id',auth,admin,async(req,res)=>{if(pool){const r=await q('update documents set status=$1 where id=$2 returning *',[req.body.status,req.params.id]);if(!r[0])return res.status(404).json({error:'Document not found'});return res.json(r[0])}const d=memory.documents.get(req.params.id);if(!d)return res.status(404).json({error:'Document not found'});d.status=req.body.status;res.json(d)});

app.get('/api/partner/status',auth,async(req,res)=>{if(pool){const applications=await q('select id,requested_role,business_name,status,created_at,reviewed_at from role_applications where phone=$1 order by created_at desc',[req.user.phone]);const rider=(await q('select * from rider_profiles where phone=$1',[req.user.phone]))[0]||null;const vendors=await q("select * from business_profiles where owner_phone=$1 and kind='vendor' order by created_at desc limit 1",[req.user.phone]);const hotels=await q("select * from business_profiles where owner_phone=$1 and kind='hotel' order by created_at desc limit 1",[req.user.phone]);return res.json({applications,rider,vendor:vendors[0]||null,hotel:hotels[0]||null});}return res.json({applications:[...memory.applications.values()].filter(x=>x.phone===req.user.phone),rider:memory.riders.get(req.user.phone)||null,vendor:[...memory.businesses.values()].find(x=>x.owner_phone===req.user.phone&&x.kind==='vendor')||null,hotel:[...memory.businesses.values()].find(x=>x.owner_phone===req.user.phone&&x.kind==='hotel')||null});});
app.get('/api/admin/partners',auth,admin,async(req,res)=>{if(pool){const vendors=await q("select * from business_profiles where kind='vendor' order by created_at desc limit 200");const hotels=await q("select * from business_profiles where kind='hotel' order by created_at desc limit 200");const riders=await q('select * from rider_profiles order by created_at desc limit 200');return res.json({vendors,hotels,riders});}return res.json({vendors:[...memory.businesses.values()].filter(x=>x.kind==='vendor'),hotels:[...memory.businesses.values()].filter(x=>x.kind==='hotel'),riders:[...memory.riders.values()]});});
app.patch('/api/admin/partners/:kind/:id/status',auth,admin,async(req,res)=>{const kind=String(req.params.kind);const status=cleanText(req.body.status,20);if(!['vendor','hotel','rider'].includes(kind)||!['approved','rejected','pending'].includes(status))return res.status(400).json({error:'Invalid partner status'});if(pool){let r;if(kind==='rider')r=await q('update rider_profiles set status=$1,updated_at=now() where phone=$2 returning *',[status,req.params.id]);else r=await q('update business_profiles set status=$1,updated_at=now() where id=$2 returning *',[status,req.params.id]);if(!r[0])return res.status(404).json({error:'Partner not found'});const phone=kind==='rider'?r[0].phone:r[0].owner_phone;if(status==='approved')await q('update users set role=$1,updated_at=now() where phone=$2',[kind,phone]);if(status==='rejected'&&kind!=='rider')await q("update users set role=case when role=$1 then 'customer' else role end where phone=$2",[kind,phone]);if(status==='rejected'&&kind==='rider')await q("update users set role=case when role='rider' then 'customer' else role end where phone=$1",[phone]);await audit(req.user.phone,'partner.status','partner',String(req.params.id),{kind,status});return res.json({ok:true,partner:r[0]});}const collection=kind==='rider'?memory.riders:memory.businesses;const obj=collection.get(req.params.id);if(!obj)return res.status(404).json({error:'Partner not found'});obj.status=status;const phone=kind==='rider'?obj.phone:obj.owner_phone;if(status==='approved'){const u=memory.users.get(phone);if(u)u.role=kind;}if(status==='rejected'){const u=memory.users.get(phone);if(u&&u.role===kind)u.role='customer';}res.json({ok:true,partner:obj});});
